const columnList = document.querySelector('#column-list');
if (!columnList) return;

// Only move if not already inside column-list
if (element.parentElement === columnList) return;

// Place a clone reference - move the real element before column-list
const parent = columnList.parentElement;
if (!parent) return;
parent.insertBefore(element, columnList);
element.style.order = '-4';
element.style.marginBottom = '16px';

const columnList = document.querySelector('#column-list');
if (!columnList) return;

const parent = columnList.parentElement;
if (!parent) return;

// Only move if not already before column-list
if (element.nextElementSibling === columnList) return;

parent.insertBefore(element, columnList);
element.style.marginBottom = '24px';
